def transform(grid):
    if not grid or not grid[0]:
        return grid

    background = grid[0][0]

    # Find all special pixels
    special_pixels = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != background:
                special_pixels.append((r, c))

    if not special_pixels:
        return grid

    # Get special color
    special_color = grid[special_pixels[0][0]][special_pixels[0][1]]

    any_horizontal = len(set(p[0] for p in special_pixels)) == 1
    any_vertical = len(set(p[1] for p in special_pixels)) == 1

    if not any_horizontal and not any_vertical:
        # Not a pure row or column - return input as is
        return grid

    output = [[background for _ in range(len(grid[0]))] for _ in range(len(grid))]

    if any_horizontal:
        row = special_pixels[0][0]
        for c in range(len(grid[0])):
            output[row][c] = special_color
    elif any_vertical:
        col = special_pixels[0][1]
        for r in range(len(grid)):
            output[r][col] = special_color

    return output
